    $('#toggleAdvanced')?.addEventListener('click',()=>$('#advancedFilters')?.classList.toggle('open')); $('#applyFilters')?.addEventListener('click',loadHomeListings); $('#resetFilters')?.addEventListener('click',()=>{ $$('#filterPanel input,#filterPanel select').forEach(x=>{if(x.type==='checkbox')x.checked=false;else x.value=''}); $('#vipOnly').dataset.on='0';$('#vipOnly').classList.remove('btn-gold');loadHomeListings() });
