  async function priceInsight(x){
    const {data}=await sb.from('elanlar').select('price').eq('status','approved').eq('brand',x.brand).eq('model',x.model).gte('year',x.year-2).lte('year',x.year+2).eq('currency',x.currency).limit(200); const arr=(data||[]).map(y=>Number(y.price)).filter(Boolean).sort((a,b)=>a-b); if(arr.length<3)return null; const median=arr[Math.floor(arr.length/2)]; const delta=(Number(x.price)-median)/median*100; return {median,delta,count:arr.length};
  }
  function renderDetail(x,seller,hist,insight,isFav){
    const root=$('#detailRoot'); const photos=x.image_urls?.length?x.image_urls:['assets/img/brand/icon-512.png']; const name=[seller?.name,seller?.surname].filter(Boolean).join(' ')||'Satıcı'; const wa=digits(x.whatsapp_phone||x.phone); const phone=String(x.phone||''); let priceClass='',priceLabel=''; if(insight){if(insight.delta<=-4){priceClass='good';priceLabel=t('goodPrice')}else if(insight.delta>=8){priceLabel=t('highPrice')}else priceLabel=t('marketPrice')}
    root.innerHTML=`<div class="detail-layout"><div class="stack"><section class="panel gallery"><div class="gallery-main"><img id="mainPhoto" src="${esc(photos[0])}" alt="${esc(x.title)}"></div><div class="gallery-thumbs">${photos.map((p,i)=>`<button class="gallery-thumb ${i===0?'active':''}" data-photo="${esc(p)}"><img src="${esc(p)}" alt=""></button>`).join('')}</div></section>
      <section class="panel detail-main"><div class="detail-title"><div><h1>${esc(x.brand)} ${esc(x.model)}</h1><div class="muted small">${x.year} • ${Number(x.mileage).toLocaleString(locale())} km • ${esc([x.city,x.state_name,x.country_code].filter(Boolean).join(', '))}</div></div><div class="card-badges" style="position:static;max-width:none">${listingBadges(x)}</div></div><div class="detail-price">${money(x.price,x.currency)}</div>${insight?`<div class="price-insight"><span class="badge ${priceClass}">${esc(priceLabel)}</span><span>Median: <strong>${money(insight.median,x.currency)}</strong> • ${insight.count} elan</span></div>`:''}<div class="divider"></div><div class="detail-actions"><button class="btn btn-outline ${isFav?'active':''}" id="detailFav"><i class="fa-${isFav?'solid':'regular'} fa-heart"></i>${t('favorites')}</button><button class="btn btn-outline" id="detailCompare"><i class="fa-solid fa-code-compare"></i>${t('compare')}</button><button class="btn btn-outline" id="detailShare"><i class="fa-solid fa-share-nodes"></i>${t('share')}</button></div><div class="divider"></div><div class="spec-grid">${[['İl',x.year],['Ban',x.body_type],['Mühərrik',x.engine_volume?`${x.engine_volume} L`:'-'],['Güc',x.engine_power?`${x.engine_power} a.g.`:'-'],['Yanacaq',x.fuel],['Sürətlər qutusu',x.transmission],['Ötürücü',x.drivetrain],['Rəng',x.color],['Yürüş',`${Number(x.mileage).toLocaleString()} km`],['Bazar',x.market_origin||'-'],['VIN',x.vin||'-'],['Vəziyyət',x.is_new?'Yeni':'Sürülmüş']].map(([a,b])=>`<div class="spec"><span>${esc(a)}</span><strong>${esc(b??'-')}</strong></div>`).join('')}</div><div class="divider"></div><h3>Açıqlama</h3><p style="white-space:pre-wrap">${esc(x.description||'Açıqlama əlavə edilməyib.')}</p>${x.equipment?.length?`<div class="divider"></div><h3>Təchizat</h3><div class="equipment-list">${x.equipment.map(y=>`<span class="equipment-tag"><i class="fa-solid fa-check"></i> ${esc(y)}</span>`).join('')}</div>`:''}</section>
      ${hist.length?`<section class="panel panel-pad"><div class="section-head"><h3>Qiymət tarixçəsi</h3></div><div class="price-history">${hist.map(h=>`<div class="price-row"><span>${dateText(h.created_at)}</span><strong>${money(h.new_price,h.currency)}</strong></div>`).join('')}</div></section>`:''}
      </div><aside class="detail-sidebar stack"><section class="panel seller-card"><div class="row"><img class="seller-avatar" src="${esc(seller?.avatar_url||'assets/img/brand/icon-192.png')}" alt=""><div class="grow"><strong>${esc(name)}</strong><div class="muted small">${seller?.role==='dealer'?'Diler':'Şəxsi satıcı'} ${seller?.is_verified?'<i class="fa-solid fa-circle-check" style="color:var(--info)"></i>':''}</div><div class="trust"><span>Etibar ${seller?.trust_score||50}/100</span><span class="trust-bar"><i style="width:${seller?.trust_score||50}%"></i></span></div></div></div><div class="contact-grid"><a class="btn" href="tel:${esc(phone)}"><i class="fa-solid fa-phone"></i>${t('call')}</a>${wa?`<a class="btn btn-whatsapp" target="_blank" rel="noopener" href="https://wa.me/${wa}?text=${encodeURIComponent(`Salam. AvtoVİP.az-da ${x.brand} ${x.model} (${x.year}) elanınızla maraqlanıram: ${location.href}`)}"><i class="fa-brands fa-whatsapp"></i>${t('whatsapp')}</a>`:'<button class="btn btn-outline" disabled>WhatsApp</button>'}</div>${currentUser&&currentUser.id!==x.user_id?`<a class="btn btn-outline btn-block" style="margin-top:7px" href="mesajlar.html?with=${x.user_id}&listing=${x.id}"><i class="fa-regular fa-comment"></i> Mesaj yaz</a>`:''}</section><section class="panel panel-pad"><div class="section-head"><h3>Təhlükəsiz alış</h3></div><p class="muted small">Ödəniş etməzdən əvvəl avtomobili və sənədləri yerində yoxlayın. Şübhəli elanları bizə bildirin.</p><button class="btn btn-outline btn-block" id="reportBtn"><i class="fa-regular fa-flag"></i>${t('report')}</button></section></aside></div>`;
    $$('.gallery-thumb').forEach(b=>b.onclick=()=>{$('#mainPhoto').src=b.dataset.photo;$$('.gallery-thumb').forEach(z=>z.classList.toggle('active',z===b))}); $('#detailFav').onclick=e=>toggleFavorite(x.id,e.currentTarget); $('#detailCompare').onclick=()=>toggleCompare(x.id); $('#detailShare').onclick=async()=>{try{if(navigator.share)await navigator.share({title:`${x.brand} ${x.model}`,url:location.href});else{await navigator.clipboard.writeText(location.href);toast('Link kopyalandı.','success')}}catch{}}; $('#reportBtn').onclick=()=>reportListing(x.id);
  }
  async function reportListing(id){
    const reason=prompt('Şikayətin səbəbini qısa yazın:'); if(!reason?.trim())return; const {error}=await sb.from('listing_reports').insert({listing_id:id,reporter_id:currentUser?.id||null,reason:reason.trim()}); if(error)toast(error.message,'error');else toast('Şikayət admin yoxlamasına göndərildi.','success');
  }

  async function initCreateListing(){
    const user=await db.requireAuth();if(!user)return; await commonFormOptions(); const form=$('#listingForm'); const files=$('#listingImages'); const preview=$('#imagePreview'); files?.addEventListener('change',()=>renderPreview(files.files,preview)); form?.addEventListener('submit',async e=>{e.preventDefault();const btn=$('#submitListing');btn.disabled=true;setStatus('#listingStatus','Şəkillər yüklənir...');try{const imageFiles=[...files.files].slice(0,15);if(imageFiles.length<3)throw new Error('Minimum 3 avtomobil şəkli əlavə edin.');const urls=[];for(const file of imageFiles){if(file.size>10*1024*1024)throw new Error(`${file.name} 10 MB-dan böyükdür.`);urls.push((await db.upload('elan-images',user.id,file,'listings')).url)} const fd=new FormData(form); const payload={user_id:user.id,brand:fd.get('brand'),model:fd.get('model')?.trim(),generation:fd.get('generation')?.trim(),trim:fd.get('trim')?.trim(),year:Number(fd.get('year')),price:Number(fd.get('price')),currency:fd.get('currency'),country_code:fd.get('country_code')||'AZ',state_name:fd.get('state_name')||null,city:fd.get('city'),district:fd.get('district')?.trim()||null,body_type:fd.get('body_type'),color:fd.get('color'),fuel:fd.get('fuel'),transmission:fd.get('transmission'),drivetrain:fd.get('drivetrain'),engine_volume:fd.get('engine_volume')?Number(fd.get('engine_volume')):null,engine_power:fd.get('engine_power')?Number(fd.get('engine_power')):null,mileage:Number(fd.get('mileage')||0),seats:fd.get('seats')?Number(fd.get('seats')):null,owners_count:fd.get('owners_count')?Number(fd.get('owners_count')):null,market_origin:fd.get('market_origin')?.trim(),vin:fd.get('vin')?.trim().toUpperCase(),description:fd.get('description')?.trim(),phone:fd.get('phone')?.trim(),whatsapp_phone:fd.get('whatsapp_phone')?.trim(),is_new:fd.get('is_new')==='on',is_credit:fd.get('is_credit')==='on',is_barter:fd.get('is_barter')==='on',has_accident:fd.get('has_accident')==='on',is_painted:fd.get('is_painted')==='on',equipment:fd.getAll('equipment'),image_urls:urls,status:'pending'}; if(!payload.brand||!payload.model||!payload.year||!payload.price||!payload.phone)throw new Error('Vacib sahələri doldurun.');const {data,error}=await sb.from('elanlar').insert(payload).select('id').single();if(error)throw error;setStatus('#listingStatus','Elan moderasiyaya göndərildi.','success');toast('Elan yaradıldı və admin yoxlamasına göndərildi.','success');setTimeout(()=>location.href=`profile.html?created=${data.id}`,900)}catch(err){setStatus('#listingStatus',err.message,'error');toast(err.message,'error')}finally{btn.disabled=false}});
  }
  function renderPreview(files,root){if(!root)return;root.innerHTML=[...files].slice(0,15).map(f=>`<div class="upload-tile"><img src="${URL.createObjectURL(f)}" alt=""></div>`).join('')}

  async function initCreateStory(){
    const user=await db.requireAuth();if(!user)return; const form=$('#storyForm'); const media=$('#storyMedia'); media?.addEventListener('change',()=>{const f=media.files[0],box=$('#storyPreview');if(!f||!box)return;const u=URL.createObjectURL(f);box.innerHTML=f.type.startsWith('video/')?`<video src="${u}" controls></video>`:`<img src="${u}" alt="">`}); form?.addEventListener('submit',async e=>{e.preventDefault();const btn=$('#storySubmit');btn.disabled=true;try{const file=media.files[0];if(!file)throw new Error('Şəkil və ya video seçin.');const up=await db.upload('story-media',user.id,file,'stories');const {data:story,error}=await sb.from('stories').insert({user_id:user.id,listing_id:$('#storyListing')?.value||null,media_url:up.url,media_type:file.type.startsWith('video/')?'video':'image',caption:$('#storyCaption').value.trim(),status:'pending_payment'}).select().single();if(error)throw error;const amount=Number($('#storyAmount')?.dataset.amount||5);const {error:pe}=await sb.from('payment_requests').insert({user_id:user.id,target_type:'story',target_id:story.id,plan_code:'24h',amount,payment_method:$('#storyPaymentMethod').value,payer_note:$('#storyPaymentNote').value.trim()});if(pe)throw pe;toast('Hekayə yaradıldı. Ödəniş sorğusu admin təsdiqini gözləyir.','success');setStatus('#storyStatus','Admin ödənişi təsdiqlədikdən sonra hekayə 24 saatlıq aktiv olacaq.','success');form.reset();$('#storyPreview').innerHTML='';}catch(err){toast(err.message,'error');setStatus('#storyStatus',err.message,'error')}finally{btn.disabled=false}}); const {data:list}=await sb.from('elanlar').select('id,brand,model,year').eq('user_id',user.id).eq('status','approved').order('created_at',{ascending:false}); const sel=$('#storyListing');if(sel)sel.innerHTML='<option value="">Elana bağlama</option>'+(list||[]).map(x=>`<option value="${x.id}">${esc(x.brand)} ${esc(x.model)} ${x.year}</option>`).join('');
  }

